{
  "findings": [
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded MySQL administrator password",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "HIGH",
      "explanation": "The administrator password is stored directly in Terraform source, exposing a privileged database credential through source control and Terraform history."
    },
    {
      "check_id": "CKV_AZURE_96",
      "title": "MySQL infrastructure encryption is not enabled",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server does not enable infrastructure-level encryption, leaving it without the additional encryption layer required by this policy."
    },
    {
      "check_id": "CKV2_AZURE_44",
      "title": "MySQL server lacks a private endpoint",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The MySQL server has no private endpoint and does not explicitly disable public network access, allowing connectivity outside a private Azure network path."
    },
    {
      "check_id": "CKV2_AZURE_16",
      "title": "MySQL customer-managed encryption key is not configured",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "The server has no customer-managed key association, so control and rotation of its data-encryption key remain solely with the platform."
    },
    {
      "check_id": "CKV_AZURE_54",
      "title": "Minimum TLS version is not explicitly set to TLS 1.2",
      "resource": "azurerm_mysql_server.changeme_simple_mysql_server",
      "severity": "MEDIUM",
      "explanation": "Although SSL enforcement is enabled, the minimum accepted TLS version is not specified, so obsolete TLS protocols are not explicitly prohibited."
    }
  ],
  "patched_code": "variable "mysql_administrator_password" {
  description = "Administrator password for the MySQL server."
  type        = string
  sensitive   = true
}

variable "mysql_customer_managed_key_id" {
  description = "Resource ID of the versioned Key Vault key used to encrypt the MySQL server."
  type        = string
}

variable "mysql_private_endpoint_subnet_id" {
  description = "Resource ID of the subnet in which the MySQL private endpoint is created."
  type        = string
}

resource "azurerm_mysql_server" "changeme_simple_mysql_server" {
  name                = "changeme-simple-mysql-database-name"
  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name
  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location
  storage_mb           = "5120"
  sku_name             = "B_Gen5_1"
  version              = "8.0"

  administrator_login          = "changemeadmin"
  administrator_login_password = var.mysql_administrator_password

  ssl_enforcement_enabled          = true
  ssl_minimal_tls_version_enforced = "TLS1_2"
  infrastructure_encryption_enabled = true
  public_network_access_enabled     = false

  identity {
    type = "SystemAssigned"
  }
}

resource "azurerm_mysql_server_key" "changeme_simple_mysql_server" {
  server_id        = azurerm_mysql_server.changeme_simple_mysql_server.id
  key_vault_key_id = var.mysql_customer_managed_key_id
}

resource "azurerm_private_endpoint" "changeme_simple_mysql_server" {
  name                = "changeme-simple-mysql-private-endpoint"
  location            = azurerm_resource_group.changeme_simple_mysql_server_resource_group.location
  resource_group_name = azurerm_resource_group.changeme_simple_mysql_server_resource_group.name
  subnet_id           = var.mysql_private_endpoint_subnet_id

  private_service_connection {
    name                           = "changeme-simple-mysql-private-connection"
    private_connection_resource_id = azurerm_mysql_server.changeme_simple_mysql_server.id
    is_manual_connection           = false
    subresource_names              = ["mysqlServer"]
  }
}
",
  "fix_summary": "Replaced the hardcoded administrator password with a sensitive input variable, enabled infrastructure encryption and TLS 1.2, and disabled public network access. Added a system-assigned identity, customer-managed key association, and private endpoint using caller-supplied resource IDs."
}
